import{_ as i,o as t,c as e,a2 as a}from"./chunks/framework.DXa1R37q.js";const k=JSON.parse('{"title":"Generic MCP servers","description":"","frontmatter":{},"headers":[],"relativePath":"mcp/index.md","filePath":"mcp/index.md","lastUpdated":1793126588000}'),n={name:"mcp/index.md"};function o(p,s,h,r,l,d){return t(),e("div",null,[...s[0]||(s[0]=[a('<h1 id="generic-mcp-servers" tabindex="-1">Generic MCP servers <a class="header-anchor" href="#generic-mcp-servers" aria-label="Permalink to &quot;Generic MCP servers&quot;">​</a></h1><p>Neottia ships four stdio servers. Start each process in the project directory whose <code>.neottia/config.yml</code> and canonical files it should use.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Command</th><th style="text-align:right;">Tools</th></tr></thead><tbody><tr><td>Memory</td><td><code>pnpm dlx @neottia/memory-mcp</code></td><td style="text-align:right;">9</td></tr><tr><td>Issues</td><td><code>pnpm dlx @neottia/issues-mcp</code></td><td style="text-align:right;">17</td></tr><tr><td>Design Docs</td><td><code>pnpm dlx @neottia/design-docs-mcp</code></td><td style="text-align:right;">13</td></tr><tr><td>Searchable</td><td><code>pnpm dlx @neottia/searchable-mcp</code></td><td style="text-align:right;">5</td></tr></tbody></table><h2 id="generic-client-pattern" tabindex="-1">Generic client pattern <a class="header-anchor" href="#generic-client-pattern" aria-label="Permalink to &quot;Generic client pattern&quot;">​</a></h2><p>Clients that use <code>mcpServers</code> can launch Memory like this:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;neottia-memory&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pnpm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dlx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@neottia/memory-mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] } } }</span></span></code></pre></div><p>Replace the server name and package for Issues, Design Docs, or Searchable. Keep the client process working directory at the project root.</p><h2 id="opencode-mcp-configuration" tabindex="-1">OpenCode MCP configuration <a class="header-anchor" href="#opencode-mcp-configuration" aria-label="Permalink to &quot;OpenCode MCP configuration&quot;">​</a></h2><p>OpenCode accepts a local command array in <code>opencode.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;neottia-memory&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;local&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pnpm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dlx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@neottia/memory-mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } } }</span></span></code></pre></div><p>OpenCode also has <a href="/projects/neottia/harnesses/opencode">native Neottia plugins</a>. Choose either the native plugin or generic MCP package for a capability, not both.</p><h2 id="pi-mcp-configuration" tabindex="-1">Pi MCP configuration <a class="header-anchor" href="#pi-mcp-configuration" aria-label="Permalink to &quot;Pi MCP configuration&quot;">​</a></h2><p>Pi accepts a project <code>.pi/mcp.json</code> entry:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;neottia-memory&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pnpm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dlx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@neottia/memory-mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] } } }</span></span></code></pre></div><p>Pi users should normally choose the <a href="/projects/neottia/harnesses/pi">native extensions</a>, which provide Pi confirmation behavior. The generic MCP process remains non-interactive.</p><p>All four servers advertise <code>{tools: {}}</code> and implement <code>tools/list</code> and <code>tools/call</code>. They expose no MCP resources or prompts. Keep logs off stdout because stdout carries MCP frames. Stop the client cleanly so it closes the server and its cached domain context.</p><p>The servers are non-interactive. A stale <code>prompt</code> policy rebuilds; <code>fail</code> still fails. See the <a href="/projects/neottia/mcp/memory">Memory</a>, <a href="/projects/neottia/mcp/issues">Issues</a>, <a href="/projects/neottia/mcp/design-docs">Design Docs</a>, and <a href="/projects/neottia/mcp/searchable">Searchable</a> server pages.</p>',17)])])}const E=i(n,[["render",o]]);export{k as __pageData,E as default};
